<script>
/* ---------------- data ---------------- */
const LOTS = [
  {id:207,title:"Cinematic Still, 35mm",model:"Midjourney",cat:"Image",price:9,sold:4700,rating:5.0,seller:"Atlas Studio",ar:"3/4",desc:"Film-grade stills with real lens language 鈥?focal length, grain, and lighting that reads as cinema."},
  {id:233,title:"Ink Wash Warrior",model:"Midjourney",cat:"Image",price:12,sold:2100,rating:4.9,seller:"Sumi Lab",ar:"2/3",desc:"Sumi-e meets splash ink. Dramatic monochrome heroes with controlled negative space."},
  {id:174,title:"Editorial Photo Grade",model:"Flux",cat:"Photography",price:11,sold:1300,rating:4.9,seller:"N. S酶rensen",ar:"3/4",desc:"Magazine-style color grading. Warm skin, deep shadow, that quiet print look 鈥?no garish presets."},
  {id:301,title:"Magazine Cover Maker",model:"GPT-4o",cat:"Design",price:14,sold:3300,rating:4.8,seller:"Field & Co.",ar:"4/5",desc:"Drop in a photo, get a full cover 鈥?masthead, cover lines, barcode, the works."},
